import { DEFAULT_SKY_CONFIG, type SkyConfig, type SkyRig } from "./sky";

export interface SkyTunerOptions {
  rig: SkyRig;
  /**
   * The climb's own progress setter (camera + trail), so the sun can be
   * judged at the scroll position it actually appears at. Without it the
   * elevation slider still works, but you are looking at the summit sun
   * over the base-camp framing.
   */
  setProgress?: (t: number) => void;
}

type NumericKey = {
  [K in keyof SkyConfig]: SkyConfig[K] extends number ? K : never;
}[keyof SkyConfig];

type BooleanKey = {
  [K in keyof SkyConfig]: SkyConfig[K] extends boolean ? K : never;
}[keyof SkyConfig];

interface Knob {
  key: NumericKey;
  label: string;
  min: number;
  max: number;
  step: number;
  /** Decimals to print. Defaults to whatever the step implies. */
  digits?: number;
  suffix?: string;
}

interface Group {
  title: string;
  knobs: Knob[];
  toggles?: { key: BooleanKey; label: string }[];
}

const GROUPS: Group[] = [
  {
    title: "sun traverse",
    knobs: [
      { key: "elevation", label: "sun elevation (live)", min: 0, max: 180, step: 0.5, suffix: "°" },
      { key: "elevationStart", label: "at scroll 0", min: 0, max: 180, step: 1, suffix: "°" },
      { key: "elevationEnd", label: "at scroll 1", min: 0, max: 180, step: 1, suffix: "°" },
      { key: "azimuth", label: "bearing", min: -180, max: 180, step: 1, suffix: "°" },
    ],
    toggles: [{ key: "manualElevation", label: "hold elevation (ignore scroll)" }],
  },
  {
    title: "atmosphere",
    knobs: [
      { key: "turbidity", label: "turbidity (haze)", min: 1, max: 20, step: 0.1 },
      { key: "rayleigh", label: "rayleigh (blue)", min: 0, max: 6, step: 0.05 },
      { key: "mieCoefficient", label: "mie", min: 0, max: 0.05, step: 0.0005, digits: 4 },
      { key: "mieDirectionalG", label: "mie g (sun glow)", min: 0, max: 0.999, step: 0.005 },
      { key: "luminance", label: "sky brightness", min: 0.01, max: 0.6, step: 0.005, digits: 3 },
    ],
    toggles: [{ key: "showSunDisc", label: "show sun disc" }],
  },
  {
    title: "clouds",
    knobs: [
      { key: "cloudCoverage", label: "coverage", min: 0, max: 1, step: 0.01 },
      { key: "cloudDensity", label: "density", min: 0, max: 1, step: 0.01 },
      { key: "cloudScale", label: "scale", min: 0.00005, max: 0.001, step: 0.00001, digits: 5 },
      { key: "cloudSpeed", label: "speed", min: 0, max: 0.001, step: 0.00001, digits: 5 },
      { key: "cloudElevation", label: "deck height", min: 0, max: 1, step: 0.01 },
    ],
  },
  {
    title: "light + fog",
    knobs: [
      { key: "sunIntensity", label: "key (at zenith)", min: 0, max: 8, step: 0.05 },
      { key: "ambientIntensity", label: "sky fill", min: 0, max: 3, step: 0.05 },
      { key: "fogDensity", label: "fog density", min: 0, max: 0.004, step: 0.00005, digits: 5 },
      { key: "fogSkyPitch", label: "fog sampled at", min: 0, max: 30, step: 0.5, suffix: "° up" },
      { key: "fogBrightness", label: "fog brightness", min: 0.2, max: 1.5, step: 0.01 },
    ],
    toggles: [{ key: "fogFollowsSky", label: "fog takes the sky's horizon" }],
  },
  {
    title: "shadow",
    knobs: [
      { key: "shadowIntensity", label: "strength", min: 0, max: 1, step: 0.01 },
      { key: "shadowRadius", label: "coverage", min: 100, max: 900, step: 10, suffix: "u" },
      { key: "shadowNormalBias", label: "normal bias", min: 0, max: 6, step: 0.05 },
      { key: "shadowBias", label: "depth bias", min: -0.005, max: 0.001, step: 0.0001, digits: 4 },
      { key: "shadowStepDeg", label: "redraw every", min: 0.05, max: 3, step: 0.05, suffix: "°" },
    ],
  },
];

/** Printed back in the same order and shape as the literal in sky.ts. */
const PRINT_ORDER: (keyof SkyConfig)[] = [
  "elevationStart",
  "elevationEnd",
  "azimuth",
  "turbidity",
  "rayleigh",
  "mieCoefficient",
  "mieDirectionalG",
  "luminance",
  "showSunDisc",
  "cloudCoverage",
  "cloudDensity",
  "cloudScale",
  "cloudSpeed",
  "cloudElevation",
  "sunIntensity",
  "ambientIntensity",
  "fogFollowsSky",
  "fogDensity",
  "fogSkyPitch",
  "fogBrightness",
  "shadowIntensity",
  "shadowRadius",
  "shadowBias",
  "shadowNormalBias",
  "shadowStepDeg",
];

/**
 * Dev-only sky panel, opened with ?sky.
 *
 * The sky is the one part of this scene with no good way to reason about a
 * number in the abstract: turbidity 4 against rayleigh 2 is a look, not a
 * value, and the only way to find one is to drag it while the mountain is
 * on screen. This writes straight into rig.config - which update() re-reads
 * every frame - so a slider is visible on the next frame, and prints the
 * block to paste back over DEFAULT_SKY_CONFIG once the look is right.
 *
 * Nothing here ships unless ?sky is in the URL; scene/index.ts imports it
 * dynamically, exactly as it does the camera panel.
 */
export function createSkyTuner(options: SkyTunerOptions): () => void {
  const { config } = options.rig;

  const panel = document.createElement("div");
  Object.assign(panel.style, {
    position: "fixed",
    top: "12px",
    left: "12px",
    zIndex: "2147483647",
    width: "268px",
    padding: "12px 14px",
    borderRadius: "8px",
    background: "rgba(14, 20, 32, 0.9)",
    color: "#eef3fb",
    font: "11px/1.5 ui-monospace, SFMono-Regular, Menlo, monospace",
    // The canvas sits behind everything with pointer-events off; this panel
    // is in front of it and has to take a drag.
    pointerEvents: "auto",
    backdropFilter: "blur(6px)",
    maxHeight: "calc(100vh - 24px)",
    overflowY: "auto",
  });

  const heading = document.createElement("div");
  heading.textContent = "sky + sun";
  Object.assign(heading.style, {
    fontWeight: "700",
    letterSpacing: "0.08em",
    textTransform: "uppercase",
    marginBottom: "10px",
    opacity: "0.7",
  });
  panel.appendChild(heading);

  const output = document.createElement("pre");
  Object.assign(output.style, {
    margin: "10px 0 0",
    padding: "8px",
    borderRadius: "6px",
    background: "rgba(0,0,0,0.35)",
    whiteSpace: "pre-wrap",
    fontSize: "10px",
    lineHeight: "1.45",
  });

  const syncers: (() => void)[] = [];

  const format = (value: number, knob?: Knob) => {
    const digits = knob?.digits ?? (knob && knob.step < 1 ? 2 : 0);
    return `${value.toFixed(digits)}${knob?.suffix ?? ""}`;
  };

  const render = () => {
    const lines = PRINT_ORDER.map((key) => {
      const value = config[key];
      const printed = typeof value === "number" ? String(+value.toFixed(5)) : String(value);
      const marker = value === DEFAULT_SKY_CONFIG[key] ? "  " : "* ";
      return `${marker}${key}: ${printed},`;
    });
    output.textContent = lines.join("\n");
    for (const sync of syncers) sync();
  };

  const addSlider = (knob: Knob) => {
    const row = document.createElement("label");
    Object.assign(row.style, { display: "block", margin: "0 0 8px" });

    const caption = document.createElement("span");
    Object.assign(caption.style, {
      display: "flex",
      justifyContent: "space-between",
      gap: "8px",
      opacity: "0.85",
    });
    const name = document.createElement("span");
    name.textContent = knob.label;
    const value = document.createElement("span");
    caption.append(name, value);

    const input = document.createElement("input");
    input.type = "range";
    input.min = String(knob.min);
    input.max = String(knob.max);
    input.step = String(knob.step);
    input.value = String(config[knob.key]);
    Object.assign(input.style, { width: "100%", margin: "2px 0 0", accentColor: "#c9b795" });

    input.addEventListener("input", () => {
      // Dragging the live elevation is the same gesture as asking for it to
      // stop moving - otherwise the next frame writes scroll's value back
      // over it and the slider springs home under the cursor.
      if (knob.key === "elevation") config.manualElevation = true;
      config[knob.key] = Number(input.value);
      render();
    });

    // The live elevation is written by the rig every frame, so the panel
    // follows the sun while you scroll rather than going stale.
    syncers.push(() => {
      const current = config[knob.key];
      value.textContent = format(current, knob);
      if (document.activeElement !== input) input.value = String(current);
    });

    row.append(caption, input);
    panel.appendChild(row);
  };

  const addToggle = (key: BooleanKey, label: string) => {
    const row = document.createElement("label");
    Object.assign(row.style, {
      display: "flex",
      alignItems: "center",
      gap: "6px",
      margin: "0 0 8px",
      opacity: "0.85",
    });
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = config[key];
    Object.assign(input.style, { accentColor: "#c9b795" });
    input.addEventListener("change", () => {
      config[key] = input.checked;
      render();
    });
    syncers.push(() => {
      input.checked = config[key];
    });
    const text = document.createElement("span");
    text.textContent = label;
    row.append(input, text);
    panel.appendChild(row);
  };

  for (const group of GROUPS) {
    const title = document.createElement("div");
    title.textContent = group.title;
    Object.assign(title.style, { margin: "10px 0 6px", opacity: "0.55", letterSpacing: "0.06em" });
    panel.appendChild(title);
    for (const knob of group.knobs) addSlider(knob);
    for (const toggle of group.toggles ?? []) addToggle(toggle.key, toggle.label);
  }

  if (options.setProgress) {
    const scrubLabel = document.createElement("div");
    scrubLabel.textContent = "preview progress";
    Object.assign(scrubLabel.style, {
      margin: "12px 0 2px",
      opacity: "0.55",
      letterSpacing: "0.06em",
    });
    const scrub = document.createElement("input");
    scrub.type = "range";
    scrub.min = "0";
    scrub.max = "1";
    scrub.step = "0.005";
    scrub.value = "0";
    Object.assign(scrub.style, { width: "100%", accentColor: "#c9b795" });
    scrub.addEventListener("input", () => {
      // Scrubbing is how you see the traverse, so it also takes the hold
      // off: a held elevation would sit still through the whole scrub.
      config.manualElevation = false;
      options.setProgress?.(Number(scrub.value));
      render();
    });
    panel.append(scrubLabel, scrub);
  }

  const hint = document.createElement("div");
  hint.textContent = "* = changed. paste into DEFAULT_SKY_CONFIG in src/scene/sky.ts";
  Object.assign(hint.style, { margin: "12px 0 0", opacity: "0.55" });
  panel.append(hint, output);

  // The elevation readout has to keep up with a sun that scroll is moving,
  // not just with the sliders that move it here.
  const frame = () => {
    render();
    raf = requestAnimationFrame(frame);
  };
  let raf = requestAnimationFrame(frame);

  document.body.appendChild(panel);

  return () => {
    cancelAnimationFrame(raf);
    panel.remove();
  };
}
